from save_review import save
save(1363,{2:'净化瓶是药剂师使用的手榴弹，起爆后会在周围释放一团烈焰，焚烧所有接触之物。'},terms=[('Purification Vial','净化瓶')])
save(1364,{2:'热熔炸弹是一种采用热熔技术的爆破装药，常见型号大小与手榴弹相仿，也有更大的版本。起爆时，它释放强烈热能，将目标熔毁。与其他热熔武器一样，它尤其适合攻击载具、建筑和其他装甲目标。'},terms=[('Melta Bomb','热熔炸弹')])
save(1365,{2:'磷化炸弹是大远征和荷鲁斯之乱期间使用的致命磷化武器。',4:'它装填磷化燃剂，一种罕见、兼具腐蚀毒性与燃烧性的化合物。接触空气后，燃剂会膨胀成翻涌的液态雾，燃起诡异的白绿色火焰，并被运动吸引。烈焰能点燃金属、侵蚀活体组织，除了暴露于真空，几乎没有办法扑灭。尽管杀伤力可怕，这种武器仍不常用，因为它对行星的污染甚至超过辐射或核武器。因此，星际战士毁灭者只少量使用；帝国陆军的美杜莎火炮也可发射其炮弹版本，称为磷化炮弹。'},notes={4:'Phosphex统一磷化燃剂，是作品中的特殊物质，不直接当作现实的磷。Imperial Army沿帝国陆军。'},terms=[('Phosphex Bomb','磷化炸弹')])
save(1366,{2:'攻坚炸药用于摧毁装甲阵地和防御工事。与热熔炸弹类似，这种强力电化学装药过于笨重，无法投掷，近距离使用也会危及操作者；但在熟练人员手中，其破坏力极为可怕。',4:'Breacher Charge 攻坚炸药'},notes={2:'Charge此处为爆破装药，不是突击者或兵种；原名突击破坏者保留对照。'},terms=[('Breacher Charge','攻坚炸药')],title='攻坚炸药 Breacher Charge')
save(1367,{2:'遥控炸药包是星际战士侦察兵在训练期间获配的多种工具之一，适合大规模破坏和伏击。它采用遥控引爆，而非定时或碰撞触发，侦察小队可以先安放装药，再自行选择时机引爆，留出充足时间撤至安全距离。'},notes={2:'at the leisure意为可自行选择时机，不是空闲时才操作；detonation为引爆而非引燃。'},terms=[('Remote Detonation Pack','遥控炸药包')],title='遥控炸药包 Remote Detonation Pack')
save(1368,{2:'破片突击发射器由安装在十字军型和救赎者型兰德掠袭者战车车体上的多枚爆破装药组成。车内部队下车突击时，装药随之起爆，将破片抛向四周，效果类似破片手榴弹。'},terms=[('Frag Assault Launcher','破片突击发射器')])
save(1369,{2:'紊乱地雷是星际战士入侵者使用的近炸感应武器，可使敌方装甲载具失去战斗能力。',4:'Incursor with Haywire Mine 装备紊乱地雷的入侵者'},notes={2:'沿前文紊乱地雷；proximity说明接近感应引爆，而非只是作用距离近。'},terms=[('Haywire Mine','紊乱地雷')],title='紊乱地雷 Haywire Mine')
save(1370,{2:'星际战士侦察摩托小队经常携带集束地雷投入战斗。每枚地雷内有一组小型杀伤人员子炸弹，以绊线或压力感应器触发。侦察兵会用它封锁通往己方阵地的接近路线，或在敌军易受袭的通行路线上设伏，对步兵和载具均可造成严重破坏。'},terms=[('Cluster Mine','集束地雷')])
save(1371,{2:'病毒炸弹是威力强大的大规模杀伤武器，荷鲁斯之乱前常被用于执行灭绝令。后来，这一用途大多由旋风鱼雷取代，但部分帝国军械库仍保有病毒炸弹。',5:'要以病毒炸弹消灭整颗行星上的生物，舰队必须同时投射大量空爆弹头，使病毒达到足够浓度。荷鲁斯之乱初期，荷鲁斯便在伊斯塔万三号使用它，清除参战军团中被认为仍会效忠帝皇的战士。直至273.M41，巢都世界斯大林瓦斯特仍曾遭病毒炸弹灭绝。按照作品设定，炸弹中的病毒还可按特定基因编码设定目标，专门攻击异形、变种人，甚至某一种发色占多数的叛乱人类群体。',7:'伊斯塔万三号和斯大林瓦斯特使用的噬生病毒极其凶猛，数分钟便能遍布整个地表。空爆释放的病毒株吞噬空气中的细菌，扩张成游动的黑云；其极快的突变和近乎指数式的增殖，使它几秒内便能跨越物种，令动物、植物和微生物几乎瞬间腐烂。丛林与森林迅速化为污泥湖，分解的有机物释放出大量可燃气体。病毒甚至能钻入动力盔甲最细小的缝隙，进入循环呼吸器，把生物组织分解成烂泥。随后，可燃气体自行起火，或被投下的燃烧装置点燃，形成席卷全球的末日火风暴，将地表烧成裸岩，耗尽大气中的氧气。',12:'病毒炸弹也会用于战术作战。第二次阿玛吉多顿战争期间，冯·斯特拉布启用了家族在星球殖民之初秘密储存的一批炸弹。它们重创了入侵欧克，却因存放过久而效力衰减，未能达到预期效果。病毒还会随风飘移，此次使用时便倒卷向帝国卫队阵地，杀死的守军与进攻者一样多。',15:'病毒消亡后，轰炸留下的死寂岩质星球，仍可能保有宝贵的无机资源。'},notes={5:'as late as是直至该年代仍在使用，原译早在倒置了时间含义；具体病毒作用属于作品设定。',7:'Life-Eater Virus沿797已定噬生病毒，区别其他命名病毒。'},terms=[('Virus Bomb','病毒炸弹'),('Life-Eater Virus','噬生病毒')])
save(1372,{2:'铁光环是星际战士军械库中的古老遗物，也是一种特殊荣誉徽章，授予战场上表现出卓越主动性或勇气的战士。它内置强大的转换力场，类似玫瑰念珠或折射力场，可在动力盔甲之外提供额外防护，使佩戴者承受极为猛烈的攻击。',7:'铁光环通常是灰铁制成、带尖刺的圆环或半环，佩戴于头盔或左肩甲。有些形制更精巧，像真正的光环一样拱立于战斗兄弟头顶，连接颈甲或背包。少数光环还镶刻有颂扬佩戴者功绩的祷词，或战团英雄的名字。',11:'铁光环也是阿斯塔特修会的等级标志，由战团长授予。多数战团只颁给连长及以上人员；极限战士中，则只有连长和连队冠军获准佩戴。它象征战士在战场上的指挥权限与责任：同袍会期待他领导，若没有更高级的军官在场，战术决策往往由他承担。在死亡守望服役时，原有等级大体只是形式，但熟悉战团层级的星际战士和帝国士兵通常仍会尊重他的判断。指挥官也可能据此委派任务，因为佩戴者已证明自己的领导能力，是特定战况下可以倚重的人选。',13:'血鸦珍藏着一枚特殊铁光环，被奉为重要遗物，据信曾属于他们身份未知的原体。',22:'戴维安·图勒——血鸦连长。'},notes={2:'conversion field沿815转换力场，区别折射力场及Shift Field偏转力场。',11:'各战团授予对象按原文分别保留；与图注原铸副官也佩戴的情况不强行抹平。',22:'Blood Ravens为血鸦，原译圣血天使混淆战团。'},terms=[('Iron Halo','铁光环')])
save(1373,{2:'星际战士智库员使用灵能兜帽，抵御敌方灵能攻击。',4:'Ultramarine Librarian wearing a psychic hood 戴着灵能兜帽的极限战士智库员',6:'灵能兜帽通常呈金属罩形，从动力盔甲背板向上延伸。内部精密排列、相互交织的晶体用来抵消敌方灵能，但其设计极为玄奥，制造未必完美，因此效果并非绝对。底稿将荷鲁斯之乱期间一些智库员投向混沌、成为混沌巫师，作为这种局限的例证。审判官偶尔也会使用灵能兜帽。'},notes={6:'原文将防御灵能攻击与抵御混沌腐化并提，因果关系未另说明，按底稿论述保留而不补设机制。'},terms=[('Psychic Hood','灵能兜帽')],title='灵能兜帽 Psychic Hood')
save(1374,{2:'神经护罩是资深智库员使用的特殊灵能兜帽，神经动力外壳中的共振晶体已注入高强度亚空间能量。佩戴它需要极度专注，却能投射异常强大的反灵能力场。'},notes={2:'empyric指亚空间性质，不是电磁能量。'},terms=[('Neural Shroud','神经护罩')])
save(1375,{2:'偏转力场是一种由导师战团进行实战测试的先进帝国防护技术，发生器可挂在星际战士的腰带或背带上。启动后，它在约十名星际战士周围形成屏障，扭曲附近光线，使敌人无法用射弹武器准确瞄准。屏障内的导师战团战士仍可正常观察外界、向外射击，但力场无法阻止敌人进入；一旦敌人进入屏障，其保护效果也就失去作用。'},terms=[('Shift Field','偏转力场')],title='偏转力场 Shift Field')
